BEGIN;
CREATE TABLE IF NOT EXISTS documentos_compra (id SERIAL PRIMARY KEY,requisicao_compra_id INTEGER NOT NULL,tipo TEXT NOT NULL,numero TEXT NOT NULL,serie TEXT,data_emissao TEXT NOT NULL,fornecedor_id INTEGER NOT NULL,fornecedor_nome_snapshot TEXT NOT NULL,valor_total NUMERIC(15,2) NOT NULL,observacao TEXT,status TEXT NOT NULL DEFAULT 'ATIVO',criado_por INTEGER,criado_por_nome TEXT NOT NULL,criado_em TIMESTAMP NOT NULL,estornado_por INTEGER,estornado_por_nome TEXT,estornado_em TIMESTAMP,motivo_estorno TEXT,chave_criacao TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS rc_atendimentos (id SERIAL PRIMARY KEY,requisicao_compra_id INTEGER NOT NULL,documento_id INTEGER NOT NULL,data_atendimento TEXT NOT NULL,observacao TEXT,status TEXT NOT NULL DEFAULT 'ATIVO',usuario_id INTEGER,usuario_nome TEXT NOT NULL,criado_em TIMESTAMP NOT NULL,estornado_por INTEGER,estornado_por_nome TEXT,estornado_em TIMESTAMP,motivo_estorno TEXT,chave_criacao TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS rc_atendimento_itens (id SERIAL PRIMARY KEY,atendimento_id INTEGER NOT NULL,requisicao_compra_item_id INTEGER NOT NULL,quantidade NUMERIC(15,4) NOT NULL,preco_unitario_real NUMERIC(15,4) NOT NULL,valor_real NUMERIC(15,2) NOT NULL);
CREATE INDEX IF NOT EXISTS idx_doc_compra_rc ON documentos_compra(requisicao_compra_id,status); CREATE INDEX IF NOT EXISTS idx_rc_atendimento_rc ON rc_atendimentos(requisicao_compra_id,status); CREATE INDEX IF NOT EXISTS idx_rc_atendimento_item ON rc_atendimento_itens(requisicao_compra_item_id,atendimento_id);
COMMIT;
